using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.Json;
using System.Text.Json.Serialization;

// 1. Read file
string filePath = "input/input.csv";
if (!File.Exists(filePath))
{
    Console.WriteLine("[]");
    return;
}

string[] lines = File.ReadAllLines(filePath);
if (lines.Length < 2)
{
    Console.WriteLine("[]");
