    if (!IsNullOrnull(motherStr)) relatives.Add(CreateRelative(motherStr, "Mother"));
    if (!IsNullOrnull(brotherStr)) relatives.Add(CreateRelative(brotherStr, "Brother"));
    if (!IsNullOrnull(sisterStr)) relatives.Add(CreateRelative(sisterStr, "Sister"));

    artists.Add(new Artist
    {
